static void runEchoServer(ServerSocket serverSocket, int clientCount) {
    try { for (int i=0;i<clientCount;i++) {
        try (Socket k = serverSocket.accept();
             BufferedReader in = new BufferedReader(new InputStreamReader(k.getInputStream()));
             OutputStream out = k.getOutputStream()) {
            String linia = in.readLine();
            out.write(("ECHO: "+linia+"\n").getBytes());
        }
    } } catch (IOException e) {}
}
