interface Worker { void handle(Socket socket) throws IOException; }
Worker workerA = socket -> System.out.println("WorkerA obsluzyl klienta");
Worker workerB = socket -> System.out.println("WorkerB obsluzyl klienta");
ServerSocket serverSocket = new ServerSocket(0);
int port = serverSocket.getLocalPort();
AtomicInteger licznik = new AtomicInteger(0);
Thread serwer = new Thread(() -> {
    for (int i=0;i<4;i++) {
        try (Socket k = serverSocket.accept()) {
            Worker wybrany = licznik.getAndIncrement() % 2 == 0 ? workerA : workerB;
            wybrany.handle(k);
        } catch (IOException e) {}
    }
});
serwer.setDaemon(true);
serwer.start();
Thread.sleep(100);
for (int i=0;i<4;i++) { try (Socket k = new Socket("localhost", port)) { Thread.sleep(30); } catch (IOException e) {} }
serwer.join(3000);
