ServerSocket serverSocket = new ServerSocket(0);
int port = serverSocket.getLocalPort();
Thread serwer = new Thread(() -> {
    for (int i=0;i<5;i++) {
        try (Socket k = serverSocket.accept();
             BufferedReader in = new BufferedReader(new InputStreamReader(k.getInputStream()));
             OutputStream out = k.getOutputStream()) {
            String komenda = in.readLine();
            String odpowiedz;
            if (komenda.equals("PING")) odpowiedz = "PONG";
            else if (komenda.equals("TIME")) odpowiedz = String.valueOf(System.currentTimeMillis());
            else if (komenda.startsWith("ECHO ")) odpowiedz = komenda.substring(5);
            else odpowiedz = "UNKNOWN";
            out.write((odpowiedz+"\n").getBytes());
        } catch (IOException e) {}
    }
});
serwer.setDaemon(true);
serwer.start();
Thread.sleep(100);
String[] komendy = {"PING", "TIME", "ECHO witaj", "PING", "PING"};
for (String cmd : komendy) {
    try (Socket k = new Socket("localhost", port)) {
        k.setSoTimeout(2000);
        k.getOutputStream().write((cmd+"\n").getBytes());
        System.out.println(cmd+" -> "+new BufferedReader(new InputStreamReader(k.getInputStream())).readLine());
    } catch (IOException e) {}
}
serwer.join(3000);
serverSocket.close();
